package gg.laughtail.core;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.InventoryHolder;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;

import java.util.ArrayList;
import java.util.List;

/**
 * The chest-GUI front door. `/menu`, and the same thing under `/laughtail menu`.
 *
 * WHY A CHEST GUI AND NOT A CLIENT MOD BUTTON. The owner asked for an option in the ESC pause
 * menu. A server cannot put one there - the pause menu is rendered entirely client-side, and the
 * only way in is Lunar Client Apollo, which works for Lunar users and nobody else. A chest GUI
 * works for every Java client AND for Bedrock players through Geyser, which matters because 4.4
 * puts Bedrock support in scope. Apollo remains worth adding later as an extra door to the same
 * room, and nothing will depend on it.
 *
 * BUTTONS FOR UNBUILT FEATURES SAY SO. This is the whole reason D-0035 scheduled the GUI last: a
 * menu of buttons that silently do nothing looks like a finished server and is worse than no
 * menu, because it moves the disappointment from "that isn't built" to "this server is broken".
 * Every unbuilt entry is greyed, labelled "not built yet", and does nothing when clicked except
 * say the same thing.
 *
 * IDENTIFICATION IS BY HOLDER, NOT BY TITLE. A menu identified by its title can be spoofed by a
 * renamed chest or confused by a resource pack, and clicking in the wrong inventory would run a
 * command. A private InventoryHolder cannot be forged by a client.
 */
final class Menu implements Listener {

    /** Marks an inventory as ours. A client cannot fabricate this. */
    private static final class MenuHolder implements InventoryHolder {
        private final String page;
        private MenuHolder(String page) { this.page = page; }
        @Override public Inventory getInventory() { return null; }
    }

    private final LaughTailPlugin plugin;

    Menu(LaughTailPlugin plugin) {
        this.plugin = plugin;
    }

    // ---- building ------------------------------------------------------------

    private ItemStack item(Material m, String name, NamedTextColor colour, List<String> lore) {
        ItemStack it = new ItemStack(m);
        ItemMeta meta = it.getItemMeta();
        meta.displayName(Component.text(name, colour).decoration(TextDecoration.ITALIC, false));
        List<Component> l = new ArrayList<>();
        for (String line : lore) {
            l.add(Component.text(line, NamedTextColor.GRAY)
                .decoration(TextDecoration.ITALIC, false));
        }
        meta.lore(l);
        it.setItemMeta(meta);
        return it;
    }

    private ItemStack notBuilt(Material m, String name, String whatItWillDo, String blockedBy) {
        return item(m, name, NamedTextColor.DARK_GRAY, List.of(
            whatItWillDo,
            "",
            "NOT BUILT YET",
            blockedBy));
    }

    void openMain(Player p) {
        Inventory inv = Bukkit.createInventory(new MenuHolder("main"), 45,
            Component.text("Laugh Tale", NamedTextColor.GOLD));

        inv.setItem(10, item(Material.RED_BED, "Homes", NamedTextColor.GREEN, List.of(
            "Two free, more with Berries.",
            "Click to list your homes.")));

        inv.setItem(11, item(Material.GOLD_INGOT, "Berries", NamedTextColor.GOLD, List.of(
            "Your balance and your full ledger.",
            "Every movement is recorded permanently.")));

        inv.setItem(12, item(Material.COMPASS, "Random Teleport", NamedTextColor.AQUA, List.of(
            "Sends you to the RESOURCE world.",
            "That world is deleted every month.",
            "Mine there, build at home.")));

        inv.setItem(13, item(Material.ENDER_PEARL, "Teleport to a player", NamedTextColor.AQUA,
            List.of("Asks them first. They must accept.",
                "Nobody is ever teleported without consent.")));

        inv.setItem(14, item(Material.DIAMOND_SWORD, "Your rank", NamedTextColor.RED, List.of(
            "Rank comes from PvP and nothing else.",
            "Mining and building change it by exactly zero.")));

        inv.setItem(15, item(Material.WRITABLE_BOOK, "Rules", NamedTextColor.YELLOW, List.of(
            "The rules you accepted, and their version.")));

        // --- honestly unbuilt ---
        inv.setItem(19, notBuilt(Material.CHEST, "Shop",
            "Buy and sell at dynamic prices.", "Waiting on: the derived price table"));
        inv.setItem(20, notBuilt(Material.GOLD_BLOCK, "Auction House",
            "List items for other players to buy.", "Waiting on: Phase 3"));
        inv.setItem(21, notBuilt(Material.PAPER, "Orders / Bazaar",
            "Buy and sell orders, matched atomically.", "Waiting on: Phase 3"));
        inv.setItem(22, notBuilt(Material.PLAYER_HEAD, "Friends",
            "Add friends and see who is online.", "Waiting on: the friends commands"));
        inv.setItem(23, notBuilt(Material.ARMOR_STAND, "Cosmetics",
            "Unlocked by rank. Never bought with money.", "Waiting on: Phase 7"));
        inv.setItem(24, notBuilt(Material.OAK_SIGN, "Leaderboards",
            "Season standings and the Hall of Fame.", "Waiting on: Phase 8"));
        inv.setItem(25, notBuilt(Material.NOTE_BLOCK, "Settings",
            "Your personal toggles.", "Waiting on: Section 16"));

        if (p.hasPermission("laughtail.status")) {
            inv.setItem(40, item(Material.COMMAND_BLOCK, "Staff and Owner tools",
                NamedTextColor.LIGHT_PURPLE, List.of(
                    "Access grants, seasons, moderation.",
                    "Only visible because you hold laughtail.status.")));
        }

        inv.setItem(44, item(Material.BARRIER, "Close", NamedTextColor.RED, List.of()));
        p.openInventory(inv);
    }

    /**
     * The homes page. One bed per home, clicked to teleport.
     *
     * Built asynchronously because it reads the database, then opened on the main thread. The
     * obvious shortcut - read homes synchronously to build the inventory - would put a query
     * inside a click handler, which is the exact pattern acceptance row 25 forbids.
     */
    void openHomes(Player p) {
        plugin.getServer().getScheduler().runTaskAsynchronously(plugin, () -> {
            final java.util.List<String> names;
            final int purchased;
            try {
                names = plugin.database().homeNames(p.getUniqueId());
                purchased = plugin.database().purchasedSlots(p.getUniqueId());
            } catch (java.sql.SQLException e) {
                plugin.getServer().getScheduler().runTask(plugin, () ->
                    p.sendMessage(Component.text("Could not read your homes.",
                        NamedTextColor.RED)));
                return;
            }
            final int allowed = Math.min(Homes.MAX_HOMES, Homes.FREE_SLOTS + purchased);
            plugin.getServer().getScheduler().runTask(plugin, () -> {
                Inventory inv = Bukkit.createInventory(new MenuHolder("homes"), 27,
                    Component.text("Homes " + names.size() + "/" + allowed, NamedTextColor.GREEN));
                int slot = 0;
                for (String n : names) {
                    if (slot >= 18) break;
                    inv.setItem(slot++, item(Material.RED_BED, n, NamedTextColor.WHITE,
                        List.of("Click to teleport here.",
                                "3 second warmup - do not move.")));
                }
                if (allowed < Homes.MAX_HOMES) {
                    inv.setItem(22, item(Material.EMERALD, "Buy another slot",
                        NamedTextColor.GREEN, List.of(
                            "Cost: " + Homes.slotCost(purchased) + " Berries",
                            "The price rises with each slot.",
                            "A slot you buy is yours permanently.")));
                }
                inv.setItem(18, item(Material.ARROW, "Back", NamedTextColor.GRAY, List.of()));
                inv.setItem(26, item(Material.BARRIER, "Close", NamedTextColor.RED, List.of()));
                p.openInventory(inv);
            });
        });
    }

    private void openAdmin(Player p) {
        Inventory inv = Bukkit.createInventory(new MenuHolder("admin"), 27,
            Component.text("Laugh Tale - staff", NamedTextColor.LIGHT_PURPLE));

        inv.setItem(10, item(Material.NAME_TAG, "Access audit", NamedTextColor.GREEN, List.of(
            "Row 12: does the whitelist match paid grants?",
            "Checks both directions.")));
        inv.setItem(11, item(Material.PAPER, "Live grants", NamedTextColor.GREEN, List.of(
            "Everyone with paid access right now.")));
        inv.setItem(12, item(Material.CLOCK, "Season status", NamedTextColor.GOLD, List.of(
            "Current season, state, and the Champion.")));
        inv.setItem(13, item(Material.REDSTONE_TORCH, "Server status", NamedTextColor.AQUA,
            List.of("Plugin version, database, world rules.")));
        inv.setItem(14, item(Material.DIAMOND, "Rating engine", NamedTextColor.RED, List.of(
            "Appendix B invariants, run live.")));

        inv.setItem(22, item(Material.ARROW, "Back", NamedTextColor.GRAY, List.of()));
        p.openInventory(inv);
    }

    // ---- clicks --------------------------------------------------------------

    @EventHandler
    public void onClick(InventoryClickEvent e) {
        if (!(e.getInventory().getHolder() instanceof MenuHolder holder)) return;
        // Always cancel: this is a display, not a container. Without this a player could take
        // the buttons out of the menu and keep them.
        e.setCancelled(true);
        if (!(e.getWhoClicked() instanceof Player p)) return;
        ItemStack clicked = e.getCurrentItem();
        if (clicked == null || clicked.getType() == Material.AIR) return;

        ItemMeta meta = clicked.getItemMeta();
        if (meta == null || meta.displayName() == null) return;
        String name = net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer
            .plainText().serialize(meta.displayName());

        if (clicked.getType() == Material.BARRIER) { p.closeInventory(); return; }

        // Unbuilt entries are inert BY MARKER, not by name, so renaming a label cannot
        // accidentally make a dead button live.
        if (clicked.getType() == Material.CHEST || clicked.getType() == Material.GOLD_BLOCK
         || clicked.getType() == Material.PAPER && holder.page.equals("main")
         || clicked.getType() == Material.PLAYER_HEAD
         || clicked.getType() == Material.ARMOR_STAND
         || clicked.getType() == Material.OAK_SIGN
         || clicked.getType() == Material.NOTE_BLOCK) {
            if (holder.page.equals("main")) {
                p.sendMessage(Component.text(name + " is not built yet. "
                    + "The menu says so rather than pretending.", NamedTextColor.DARK_GRAY));
                return;
            }
        }

        if (holder.page.equals("homes")) {
            switch (clicked.getType()) {
                case RED_BED -> { p.closeInventory(); run(p, "home " + name); }
                case EMERALD -> { p.closeInventory(); run(p, "buyhome"); }
                case ARROW   -> openMain(p);
                default -> { }
            }
            return;
        }

        if (holder.page.equals("admin")) {
            switch (name) {
                case "Access audit"   -> run(p, "access audit");
                case "Live grants"    -> run(p, "access list");
                case "Season status"  -> run(p, "season status");
                case "Server status"  -> run(p, "laughtail status");
                case "Rating engine"  -> run(p, "laughtail rating");
                case "Back"           -> openMain(p);
                default -> { }
            }
            return;
        }

        switch (name) {
            case "Homes"               -> openHomes(p);
            case "Berries"             -> run(p, "berries");
            case "Random Teleport"     -> { p.closeInventory(); run(p, "rtp"); }
            case "Teleport to a player" -> {
                p.closeInventory();
                p.sendMessage(Component.text("Use /tpa <player>. They must accept.",
                    NamedTextColor.GRAY));
            }
            case "Your rank"           -> run(p, "laughtail rating");
            case "Rules"               -> { p.closeInventory(); run(p, "rules"); }
            case "Staff and Owner tools" -> {
                if (p.hasPermission("laughtail.status")) openAdmin(p);
            }
            default -> { }
        }
    }

    private void run(Player p, String command) {
        // Dispatched as the PLAYER, deliberately - so every permission check, every audit row
        // and every refusal behaves exactly as it would if they had typed it. A menu that runs
        // commands as console would be a permission bypass wearing a friendly face.
        plugin.getServer().dispatchCommand(p, command);
    }
}
LT_SRC_EOF_src_main_java_gg_laughtail_core_Menu_java

# ---- src/main/java/gg/laughtail/core/Hud.java ----
cat > "$SRC/src/main/java/gg/laughtail/core/Hud.java" <<'LT_SRC_EOF_src_main_java_gg_laughtail_core_Hud_java'
package gg.laughtail.core;

import io.papermc.paper.scoreboard.numbers.NumberFormat;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextColor;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.scoreboard.Criteria;
import org.bukkit.scoreboard.DisplaySlot;
import org.bukkit.scoreboard.Objective;
import org.bukkit.scoreboard.Scoreboard;
import org.bukkit.scoreboard.Team;

import java.sql.SQLException;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

/**
 * The sidebar HUD: icons, colour, and an animated title, with no score numbers.
 *
 * THE 1-9 ON THE RIGHT WERE SCOREBOARD SCORES. Every sidebar line has an integer score, and
 * vanilla renders it in red down the right edge. The usual workarounds are ugly - hiding them
 * behind long lines, or setting every score to the same value so they collapse. Paper 1.20.5 and
 * later expose `Objective#numberFormat`, so `NumberFormat.blank()` removes them properly. This
 * server is 26.2, so the correct tool exists and is used.
 *
 * LINES ARE RENDERED THROUGH TEAM PREFIXES, not as entry strings. A scoreboard entry is limited
 * and must be unique - which is why the previous version needed invisible padding like " " and
 * "  " to make blank lines distinct, and why a changing value meant removing and re-adding an
 * entry every refresh. Using a team per line with a fixed invisible entry and the visible text in
 * the prefix means values update in place with no flicker and no uniqueness games.
 *
 * THE ANIMATION IS A SHIMMER ACROSS THE TITLE, nothing more. It updates only the objective's
 * display name - one small packet per player per frame - at 5 frames a second. A moving sidebar
 * body would be genuinely expensive and, worse, unreadable: the eye cannot read a number that is
 * changing colour. So the data stays still and only the header moves, which is the effect people
 * actually mean by "animated scoreboard".
 *
 * COST, stated because 31.7 puts a budget on decoration: 5 title packets per second per player,
 * 120 a second at 24 players. That is trivial next to movement and chunk traffic, and it is
 * deliberately the ONLY animated element. If MSPT ever comes under pressure this is the first
 * thing that should be switched off, and the watchdog in 6.6 is where that switch belongs.
 */
final class Hud implements Listener {

    private record Snapshot(long berries, int rp, String tier, int season, int homes,
                            int homeMax, int champTitles, int kills, int deaths) { }

    /** The shimmer palette - gold moving through pale yellow and back. */
    private static final List<TextColor> SHIMMER = List.of(
        TextColor.fromHexString("#FFB302"),
        TextColor.fromHexString("#FFC93C"),
        TextColor.fromHexString("#FFE07D"),
        TextColor.fromHexString("#FFF3C4"),
        TextColor.fromHexString("#FFE07D"),
        TextColor.fromHexString("#FFC93C")
    );

    private static final String TITLE_TEXT = "LAUGH TALE";

    private final LaughTailPlugin plugin;
    private final Database db;
    private final Map<UUID, Snapshot> cache = new ConcurrentHashMap<>();
    private int frame = 0;

    Hud(LaughTailPlugin plugin, Database db) {
        this.plugin = plugin;
        this.db = db;
    }

    void start() {
        // Body every second: values change slowly and a redraw is cheap.
        plugin.getServer().getScheduler().runTaskTimer(plugin, this::renderAll, 20L, 20L);
        // Title every 4 ticks: 5 frames a second is smooth enough to read as movement without
        // being a flicker.
        plugin.getServer().getScheduler().runTaskTimer(plugin, this::animateAll, 20L, 4L);
        // Data every 10 seconds, off the main thread. See the class note on row 25.
        plugin.getServer().getScheduler().runTaskTimerAsynchronously(plugin, this::refreshAll,
            20L, 200L);
    }

    @EventHandler
    public void onJoin(PlayerJoinEvent e) {
        plugin.getServer().getScheduler().runTaskAsynchronously(plugin,
            () -> refresh(e.getPlayer().getUniqueId()));
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent e) {
        cache.remove(e.getPlayer().getUniqueId());
    }

    private void refreshAll() {
        for (Player p : plugin.getServer().getOnlinePlayers()) refresh(p.getUniqueId());
    }

    private void refresh(UUID id) {
        try {
            int season = db.activeSeason();
            int rp = db.currentRp(id, season);
            int[] kd = db.killsAndDeaths(id);
            cache.put(id, new Snapshot(
                db.balance(id), rp, Rating.tierName(rp), season,
                db.homeNames(id).size(),
                Math.min(Homes.MAX_HOMES, Homes.FREE_SLOTS + db.purchasedSlots(id)),
                db.championSeasons(id).size(), kd[0], kd[1]));
        } catch (SQLException e) {
            // Keep the previous snapshot. Stale beats a sidebar that flickers empty.
            plugin.getLogger().fine("HUD refresh failed: " + e.getMessage());
        }
    }

    // ---- rendering -----------------------------------------------------------

    private Objective objectiveFor(Player p) {
        Scoreboard board = p.getScoreboard();
        if (board == plugin.getServer().getScoreboardManager().getMainScoreboard()) {
            board = plugin.getServer().getScoreboardManager().getNewScoreboard();
            p.setScoreboard(board);
        }
        Objective o = board.getObjective("laughtail");
        if (o == null) {
            o = board.registerNewObjective("laughtail", Criteria.DUMMY, title(0));
            o.setDisplaySlot(DisplaySlot.SIDEBAR);
            // The whole reason the numbers are gone.
            o.numberFormat(NumberFormat.blank());
        }
        return o;
    }

    /** The shimmering header. Each character takes its colour from a moving offset. */
    private Component title(int f) {
        Component out = Component.text("\u2726 ", TextColor.fromHexString("#FFF3C4"));
        for (int i = 0; i < TITLE_TEXT.length(); i++) {
            TextColor c = SHIMMER.get(Math.floorMod(i + f, SHIMMER.size()));
            out = out.append(Component.text(String.valueOf(TITLE_TEXT.charAt(i)), c)
                .decoration(TextDecoration.BOLD, true));
        }
        return out.append(Component.text(" \u2726", TextColor.fromHexString("#FFF3C4")));
    }

    private void animateAll() {
        frame++;
        for (Player p : plugin.getServer().getOnlinePlayers()) {
            if (cache.containsKey(p.getUniqueId())) {
                objectiveFor(p).displayName(title(frame));
            }
        }
    }

    private void renderAll() {
        for (Player p : plugin.getServer().getOnlinePlayers()) {
            Snapshot s = cache.get(p.getUniqueId());
            if (s != null) render(p, s);
        }
    }

    /**
     * One team per line. The entry is an invisible unique marker and the visible text lives in
     * the team prefix, so a value can change without removing and re-adding anything.
     */
    private void line(Scoreboard board, Objective o, int index, Component text) {
        String key = "lt" + index;
        Team t = board.getTeam(key);
        if (t == null) {
            t = board.registerNewTeam(key);
            // A colour code as the entry: invisible, unique per line, and stable.
            t.addEntry("\u00A7" + "0123456789abcdef".charAt(index % 16) + "\u00A7r");
        }
        t.prefix(text);
        o.getScore(t.getEntries().iterator().next()).setScore(30 - index);
    }

    private void render(Player p, Snapshot s) {
        Objective o = objectiveFor(p);
        Scoreboard board = p.getScoreboard();
        int i = 0;

        line(board, o, i++, Component.text("\u2694 ", NamedTextColor.RED)
            .append(Component.text("Rank ", NamedTextColor.GRAY))
            .append(Component.text(s.tier(), NamedTextColor.WHITE)));

        line(board, o, i++, Component.text("\u2605 ", NamedTextColor.AQUA)
            .append(Component.text("RP ", NamedTextColor.GRAY))
            .append(Component.text(String.valueOf(s.rp()), NamedTextColor.WHITE)));

        line(board, o, i++, Component.text("\u2620 ", NamedTextColor.DARK_RED)
            .append(Component.text("K/D ", NamedTextColor.GRAY))
            .append(Component.text(s.kills() + "/" + s.deaths(), NamedTextColor.WHITE)));

        line(board, o, i++, Component.empty());

        line(board, o, i++, Component.text("\u25C8 ", NamedTextColor.GOLD)
            .append(Component.text("Berries ", NamedTextColor.GRAY))
            .append(Component.text(String.valueOf(s.berries()), NamedTextColor.YELLOW)));

        line(board, o, i++, Component.text("\u2302 ", NamedTextColor.GREEN)
            .append(Component.text("Homes ", NamedTextColor.GRAY))
            .append(Component.text(s.homes() + "/" + s.homeMax(), NamedTextColor.WHITE)));

        if (s.champTitles() > 0) {
            line(board, o, i++, Component.text("\u265B ", NamedTextColor.GOLD)
                .append(Component.text("Champion ", NamedTextColor.GRAY))
                .append(Component.text("x" + s.champTitles(), NamedTextColor.GOLD)));
        }

        line(board, o, i++, Component.empty());

        line(board, o, i++, s.season() > 0
            ? Component.text("\u25F7 ", NamedTextColor.LIGHT_PURPLE)
                .append(Component.text("Season ", NamedTextColor.GRAY))
                .append(Component.text(String.valueOf(s.season()), NamedTextColor.WHITE))
            : Component.text("\u25F7 ", NamedTextColor.DARK_GRAY)
                .append(Component.text("No active season", NamedTextColor.DARK_GRAY)));

        line(board, o, i++, Component.text("\u2726 ", TextColor.fromHexString("#FFE07D"))
            .append(Component.text("/menu", NamedTextColor.WHITE)));

        // Any line left over from a previous render - for instance the Champion line after a
        // reset - must be removed or it would linger with stale text.
        for (int stale = i; stale < 16; stale++) {
            Team t = board.getTeam("lt" + stale);
            if (t != null) {
                for (String entry : t.getEntries()) board.resetScores(entry);
                t.unregister();
            }
        }
    }
}
LT_SRC_EOF_src_main_java_gg_laughtail_core_Hud_java

echo "=== source staged ==="
find "$SRC/src" "$SRC/pom.xml" -type f | sort | while read -r f; do
  echo "  $(wc -l < "$f" | tr -d " ") lines  ${f#$SRC/}"
done

echo "=== is the image present, and is it the right architecture? ==="
sudo -n docker pull "$IMAGE" 2>&1 | tail -2
sudo -n docker inspect "$IMAGE" --format 'arch={{.Architecture}}'

echo "=== compiling ==="
# --memory 640m: this box has roughly 300 MB spare with the server running
# (baselines.md B3), so an unbounded maven JVM could push the host into OOM and
# take the game server with it. Capped deliberately, and the cap is generous
# enough for a six-file project.
#
# The .m2 cache is mounted so a rebuild does not re-download the world - the
# first build fetches Paper API and the MariaDB driver, later ones do not.
set +e
sudo -n docker run --rm \
  --memory 640m --memory-swap 640m \
  --cpus 1.5 \
  -u "$(id -u ubuntu):$(id -g ubuntu)" \
  -e HOME=/var/maven \
  -e MAVEN_CONFIG=/var/maven/.m2 \
  -v "$SRC":/src \
  -v "$M2":/var/maven/.m2 \
  -w /src \
  "$IMAGE" mvn -B -q -DskipTests -Dmaven.repo.local=/var/maven/.m2/repository package 2>&1 | tail -30
RC=${PIPESTATUS[0]}
set -e
echo "maven exit: $RC"
if [ "$RC" -ne 0 ]; then
  echo "BUILD FAILED - installing nothing."
  exit 3
fi

JAR="$SRC/target/LaughTail-$VERSION.jar"
if [ ! -s "$JAR" ]; then
  echo "BUILD REPORTED SUCCESS BUT THERE IS NO JAR - refusing to continue."
  ls -la "$SRC/target" 2>/dev/null | head
  exit 4
fi
echo "=== built ==="
ls -l "$JAR" | sed 's/^/  /'
sha256sum "$JAR" | sed 's/^/  /'

echo "=== the jar must contain the plugin descriptor and the shaded driver ==="
# `jar tf`, not `unzip -l`: the maven image ships a JDK but no unzip, and the
# first version of this check died on that after a successful build.
sudo -n docker run --rm -v "$SRC":/src -w /src "$IMAGE" \
  sh -c "jar tf target/LaughTail-$VERSION.jar | grep -E '^plugin.yml$|^config.yml$|LaughTailPlugin.class|RulesGate.class|Database.class|gg/laughtail/libs/mariadb/' | head -8"
echo "--- driver classes shaded and relocated: ---"
sudo -n docker run --rm -v "$SRC":/src -w /src "$IMAGE" \
  sh -c "jar tf target/LaughTail-$VERSION.jar | grep -c '^gg/laughtail/libs/mariadb/'"
echo "--- and NO unrelocated org/mariadb (0 expected, or the relocation silently failed): ---"
sudo -n docker run --rm -v "$SRC":/src -w /src "$IMAGE" \
  sh -c "jar tf target/LaughTail-$VERSION.jar | grep -c '^org/mariadb/' || true"

echo "=== installing into the server ==="
# The old jar is replaced, not left beside the new one - two versions of the
# same plugin in plugins/ is a load-order coin toss.
sudo -n rm -f "$D/plugins"/LaughTail-*.jar
sudo -n cp "$JAR" "$D/plugins/LaughTail-$VERSION.jar"
sudo -n chown $OWN "$D/plugins/LaughTail-$VERSION.jar"
sudo -n chmod 644 "$D/plugins/LaughTail-$VERSION.jar"
sudo -n ls -l "$D/plugins" | grep -i laughtail | sed 's/^/  /'

echo "=== disk after ==="
df -h --output=avail,pcent / | tail -1
sudo -n du -sh "$M2" 2>/dev/null | sed 's/^/  maven cache /'
echo "PLUGIN BUILT AND INSTALLED"
echo "=== END ==="
